-- ============================================================================
-- 적정성평가 Q&A — 병원 실무 카톡 질의응답 추출 2차 (2026-08-05)
--   · 원천 : 8개 병원 심사담당자 ↔ 위너넷 컨설팅 카카오톡(2025-12-29 ~ 2026-08-05)
--            에서 <업무 질문 + 위너넷 답변>을 추출·일반화. 병원명·환자명·계정정보 제거.
--   · 제외 : 점수 관리 요령성 답변(개선 폭 배분, 평가군·격리일 조정 등), 답변이 없는 질문,
--            1차(TBL_QNA_ask_20260805.sql, 38건)와 겹치는 주제(욕창 개선판정·자보 배뇨일지·
--            유치도뇨관 14일 기산 등)는 넣지 않음.
--   · HIT_CNT : 8개 대화에서 실제로 물어본 횟수(병원 수 기준) 씨앗값.
--   · SORT_NO : 1차와 충돌하지 않도록 101부터 시작.
--   · 실행 : 운영 DB(WNN)에 전체 실행. 화면 배포 불필요. KB_CODE UNIQUE — 재실행 시 오류면 이미 반영된 것.
-- ============================================================================

-- ══ 환자평가표 작성 (IN_PAT) ════════════════════════════════════════════════


-- ══ 지표 산정 (IN_IND) ══════════════════════════════════════════════════════


-- ══ 수가·청구 실무 (IN_FEE) ═════════════════════════════════════════════════


-- ── 확인 ────────────────────────────────────────────────────────────────────
SELECT CAT_ID, COUNT(*) FROM TBL_QNA_KB WHERE SRC_NM LIKE '%2026-08-05, 8개 병원%' GROUP BY CAT_ID;
-- 기대: IN_PAT 25 / IN_IND 8 / IN_FEE 16 = 총 49건

-- ── 1차(청암) 항목 중 이번 8개 병원 대화에서도 반복 질문된 주제 — HIT_CNT 가산 ──
UPDATE TBL_QNA_KB SET HIT_CNT = HIT_CNT + 3 WHERE KB_CODE = 'ask-ind-sore-count';    -- 욕창 개선 판정(단계·개수)
UPDATE TBL_QNA_KB SET HIT_CNT = HIT_CNT + 3 WHERE KB_CODE = 'ask-ind-bladder-jabo';  -- 자보·산재 배뇨관리 대상 여부
UPDATE TBL_QNA_KB SET HIT_CNT = HIT_CNT + 3 WHERE KB_CODE = 'ask-pat-prev-apply';    -- 당월 적용할 평가표 없음·이전적용
UPDATE TBL_QNA_KB SET HIT_CNT = HIT_CNT + 2 WHERE KB_CODE = 'ask-ind-foley-14d';     -- 유치도뇨관 14일 관리 시점
UPDATE TBL_QNA_KB SET HIT_CNT = HIT_CNT + 1 WHERE KB_CODE = 'ask-pat-sore-hist';     -- 욕창 과거력 기재
