INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,HIT_CNT,SORT_NO) VALUES
('ask-pat-evaltype','IN_PAT',NULL,'IN','CARD','평가구분(입원·계속입원·이전평가표 적용)은 어떻게 고르나요?','평가구분(입원·계속입원·이전적용) 고르는 법','평가구분 입원평가 계속입원중인평가 이전평가표적용 작성일 관찰기간 특정기간종료 외국인 일반 건보전환','기준은 <b>작성일</b>입니다.\n· 작성일이 <b>전월</b>이면 → 이전평가표 적용\n· 작성일이 <b>당월</b>이면 → 계속입원중인평가\n관찰기간이 겹치지 않는다면 당월 평가표를 새로 작성해도 되며, 이때 월초(1일자) 평가군과 동일해야 합니다.\n특정기간(폐렴 등)으로 입원 초 평가를 못 했다가 종료 후 작성하는 경우도 <b>계속입원중인평가</b>입니다. 당화혈색소 입원 3개월 제외는 평가표상 입원일자 기준이므로 평가구분과 무관하게 적용됩니다.\n일반(비급여)으로 있다가 건강보험으로 전환된 환자도 청구명세서상 입원일자가 그대로 이어지므로 <b>계속입원평가</b>로 작성합니다.',NULL,'ask-pat-prev-apply','병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,4,101),
('ask-pat-writer-duty','IN_PAT',NULL,'IN','CARD','평가표 작성일에 작성 간호사가 꼭 근무 중이어야 하나요?','작성일에 작성 간호사가 근무여야 하나요','작성간호사 근무여부 작성일 담당간호사','아닙니다. 환자평가표는 당해 환자를 담당하는 의사·간호사가 의무기록을 근거로 작성하면 되고, 작성일에 해당 간호사가 실제 근무했는지까지 확인하지는 않습니다.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,1,102),
('ask-pat-iv-fructose','IN_PAT',NULL,'IN','CARD','평가표 정맥주사 항목에 과당(수액)도 해당되나요?','정맥주사 항목에 과당도 되나요','정맥주사 과당 수액 포도당 해당여부','해당되지 않습니다. 단순 수액(과당 등)은 평가표의 정맥주사 항목으로 인정되지 않습니다.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,1,103),
('ask-pat-tpn','IN_PAT',NULL,'IN','CARD','중심정맥영양(최고도)은 어떤 수액이 인정되나요?','중심정맥영양은 어떤 수액이 인정되나요','중심정맥영양 TPN 네프리솔 최고도 금식','<b>TPN(총정맥영양)을 실시한 경우에만</b> 인정됩니다. 네프리솔 같은 일반 아미노산 수액은 해당되지 않습니다.\n또한 최고도(중심정맥영양) 체크는 금식 상태에서 TPN이 들어갈 때 인정되는 것이므로, 경구·경관 섭취와 병행 중이라면 인정 여부를 먼저 확인해야 합니다.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,1,104),
('ask-pat-outing-tpn','IN_PAT',NULL,'IN','CARD','외박 기간이 낀 최고도(TPN·산소) 환자 평가표는 어떻게 하나요?','외박 낀 최고도(TPN·산소) 평가표','외박 중심정맥영양 산소투여일수 최고도 작성일','외박 중에는 TPN·산소가 시행되지 않았을 텐데, 최고도(중심정맥영양)나 산소투여는 <b>실제 시행된 날만</b> 인정됩니다.\n외박 기간을 관찰기간에 포함해 작성일을 잡으면 "외박 중에는 어떻게 시행했는가"를 설명할 수 없게 되므로, 작성일과 투여일수는 외박 이후 실제 시행 기록으로 뒷받침되도록 잡아야 합니다.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,1,105),
('ask-pat-sore-photo','IN_PAT',NULL,'IN','CARD','욕창 깊이 측정과 사진은 어떻게 남기나요? (병변 2개 판단)','욕창 깊이 측정·사진 남기는 법','욕창깊이 면봉 사진촬영 병변분리 2단계 3단계 판단','깊이를 잴 때는 <b>면봉으로 찔러 깊이를 표시한 상태로 사진</b>을 찍어 두면 됩니다.\n붙어 있는 병변을 두 개로 나눌지 판단이 애매하면 원칙적으로 하나로 보되, 나누려면 <b>사진도 나눠서(분리해서) 촬영</b>해야 합니다. 단계 판단이 애매한 경우 깊이가 깊었던 욕창에 대해서만 3단계 여부를 재판단하면 됩니다.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,2,106),
('ask-pat-weight','IN_PAT',NULL,'IN','CARD','욕창 환자 체중을 측정할 수 없으면 어떻게 하나요?','욕창 환자 체중 측정 못하면','체중측정 욕창 와상 측정기구없음 추정 평가기간','욕창 환자는 평가표 작성기간 안에 체중값이 있어야 합니다.\n체중계를 쓸 수 없는 와상 환자라도 "어떻게 측정했는지"까지 기록하지는 않으므로, <b>추정치라도 입력</b>해야 합니다.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,2,107),
('ask-pat-foley-change','IN_PAT',NULL,'IN','CARD','유치도뇨관 교체·재입원 시 삽입/제거일은 어떻게 기재하나요?','유치도뇨관 교체·재입원 시 기재법','유치도뇨관 삽입일 제거일 체인지 교체 재입원 관찰기간 기재범위','<b>교체(체인지)</b>는 두 줄로 기재합니다 — ① 삽입일자 공란 / 제거일자 = 교체일, ② 삽입일자 = 교체일 / 제거일자 공란. 관찰기간 이전의 과거 삽입 이력은 관찰기간에 걸리는 마지막 교체분부터 적으면 됩니다.\n<b>퇴원 후 재입원</b>(하루 이상 공백)이면 재입원 평가표에는 삽입일만 기재합니다.\n<b>기재 범위</b>: 전월 평가표가 없었던 환자라면 입원일부터 이번 작성일까지의 기록을 모두 기재하고, 전월 평가표가 있으면 전월 작성일 다음날(통상 전월 1일)부터 이번 작성일까지가 관찰기간입니다.',NULL,'ask-ind-foley-14d','병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,4,108),
('ask-pat-foley-order','IN_PAT',NULL,'IN','CARD','폴리 KEEP 오더를 매일 내야 하나요? (오더·기록 관리)','폴리 KEEP 오더 매일 내야 하나요','foley keep 오더 데일리 삽입오더 제거오더 간호기록 사망 제거없이','매일 KEEP 오더를 낼 필요는 없습니다. 의사가 <b>삽입·제거 오더</b>를 내고, 유지 중임은 <b>간호기록에서 관리</b>되고 있으면 의무기록 불일치로 집계되지 않습니다.\n제거 오더(예: 14시 제거)와 같은 날 아침의 KEEP 오더가 함께 남아 있으면 KEEP 오더는 삭제하는 것이 가장 좋고, 삭제가 어렵다면 오더·액팅 시간이 제거 시각보다 앞서므로 넘어가도 됩니다.\n제거하지 못한 채 사망한 경우, 당월 평가표 작성일 기준 14일 초과가 아니었다면 다음달 평가표를 작성하지 않으므로 문제되지 않습니다.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,3,109),
('ask-pat-urine-record','IN_PAT',NULL,'IN','CARD','''가끔 실금함'' 환자의 간호기록은 어떻게 써야 안전한가요?','가끔실금 간호기록 예문','가끔실금 간호기록 예문 기저귀 요의 소변조절 실금기록 신뢰도점검','심평원 적정성평가지원부는 "환자가 요의를 인지하고 간호사·간병사 안내에 따라 기저귀에 배뇨하면 조절 가능으로 볼 수 있다"고 안내하지만, 운영부는 기저귀 배뇨 자체를 실금으로 해석하는 등 <b>부서별 해석 차이</b>가 있습니다.\n따라서 ''가끔 실금함''으로 작성할 때는 요의 인지 여부, 배뇨 전 안내, 실금 발생 여부가 기록에서 확인되도록 <b>조절 상태와 실금 상태를 함께</b> 기록해야 합니다. "간헐적 실금 관찰됨"만 반복되면 근거가 부족할 수 있습니다.\n<b>예문</b>\n· "요의 표현 가능하며 대부분 소변 조절 가능하나 간헐적 실금 관찰됨"\n· "기저귀 착용 중이나 실금 없이 배뇨 조절 가능하며 소변기/대변기 대어주어 소변 봄"\n· "소변 5회 중 1~2회 실금 관찰됨"\n· 대변과 소변 상태가 다르면 반드시 분리 기재: "대변조절 못해 기저귀 착용 중이나 소변은 조절 가능함"\n"대소변 화장실 이용하여 해결하나 간헐적으로 실금함"처럼 대소변을 묶어 쓰면 둘 다 가끔실금으로 읽히므로 피해야 합니다.',NULL,'ask-pat-urine-level','병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,5,110),
('ask-pat-diaper-mismatch','IN_PAT',NULL,'IN','CARD','''조절할 수 있음''인데 기저귀 착용이면 모순인가요?','조절할수있음+기저귀 착용 모순?','조절할수있음 기저귀착용 모순 오류 와상 인지있음','네, 점검 대상입니다. 대소변을 다 조절할 수 있는데 기저귀를 착용하고 있으면 "왜 착용하는지"가 설명되지 않아 오류로 잡힙니다. ''가끔 실금함''이라면 기저귀 착용이 자연스럽습니다.\n인지가 있어도 와상으로 기저귀를 쓰는 환자라면 ''조절할 수 있음''이 아니라 대변이라도 <b>가끔 실금함 또는 조절 못함</b>으로 체크하는 것이 맞습니다.',NULL,'ask-pat-urine-record','병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,2,111),
('ask-pat-rehab-sheet','IN_PAT',NULL,'IN','CARD','재활평가지(치료실 기록)도 평가표와 맞춰야 하나요?','재활평가지도 평가표와 맞춰야 하나요','재활평가지 방광컨트롤 화장실사용 불일치 현지조사 대소변조절','네. <b>현지조사 때는 재활평가지(치료실 평가기록)도 포함해서 점검</b>하므로, 평가표를 ''가끔 실금''으로 관리한다면 재활평가지의 방광 컨트롤·화장실 사용 항목이 ''조절 못함''으로 남아 있지 않은지 함께 살펴야 합니다.\nADL 기록에 "대소변 조절이 어렵다" 같은 묶음 문구가 있으면 삭제하고 대변·소변을 분리해 작성하는 것이 맞습니다.',NULL,'ask-pat-urine-record','병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,2,112),
('ask-pat-hba1c','IN_PAT',NULL,'IN','CARD','당화혈색소(HbA1c)가 높으면 언제까지 재검·확인해야 하나요?','당화혈색소 높으면 언제까지 재검?','당화혈색소 HbA1c 8.4 적정범위 입원3개월 재입원 재검사 채혈거부 검사결과지','<b>입원 3개월 미만은 지표에서 제외</b>되며, 기준은 평가표상 입원일자입니다. 퇴원 후 다시 입원하면 마지막 입원일 기준으로 다시 계산합니다(예: 3월 말 퇴원 후 5월 재입원, 첫입원 때 10.2였어도 재입원 3개월까지는 제외).\n3개월이 지나는 달부터는 <b>해당월 평가표 작성일 전에 적정범위(8.4% 미만) 결과가 확인</b>되어야 합니다. 반대로 12월 평가표를 이미 작성한 뒤 12월 말에 높은 결과가 나온 경우는 평가기간이 지났으므로 무방합니다.\n채혈을 거부하는 환자라도 BST·치료식·당뇨약이 나가는 이상 상병을 뺄 수 없으므로 의사·간호사 설득 또는 보호자 방문 하에 검사를 시행해야 합니다.\n신뢰도 점검 제출용 결과지는 EMR 화면보다 <b>검사업체 사이트에서 내려받은 결과지</b>가 좋습니다.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,5,113),
('ask-pat-hba1c-nodx','IN_PAT',NULL,'IN','CARD','당뇨 상병 없이 당화혈색소 검사만 시행해도 되나요?','당뇨 상병 없이 HbA1c 검사만?','당뇨상병없음 당화혈색소검사 정액수가 청구 신뢰도점검','정액수가 환자가 당뇨 상병 없이(약 없이) 검사만 시행한 것이라면 괜찮습니다 — 당뇨 상병을 기재하지 말고 청구하면 지표 분모에 들어가지 않습니다.\n반대로 결과가 높아 <b>당뇨약이 들어가기 시작하면</b> 상병 기재가 필요하고, 상병·약이 있는데 평가표에 당뇨 체크가 없으면 신뢰도 점검 대상이 됩니다. 정기적으로 BST·당화혈색소를 관리할 계획이면 그 달 명세서부터 상병을 넣어 관리하면 됩니다.',NULL,'ask-pat-hba1c','병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,2,114),
('ask-pat-dmfoot','IN_PAT',NULL,'IN','CARD','당뇨약을 안 먹는 환자도 당뇨발(질병진단)을 체크할 수 있나요?','당뇨약 없이 당뇨발 체크 가능?','당뇨발 질병진단 당뇨약미복용 당화혈색소 당뇨식','가능합니다. 당뇨약을 복용하지 않더라도 병변이 당뇨발로 인한 것이면 체크할 수 있습니다. 다만 당화혈색소 검사가 시행되고 있는지(당뇨 관리 근거)는 함께 확인해 두어야 합니다.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,1,115),
('ask-pat-dialysis-urine','IN_PAT',NULL,'IN','CARD','투석 환자(소변량 거의 없음)의 소변조절 상태는 어디에 체크하나요?','투석환자 소변조절 체크','투석환자 소변조절 무뇨 핍뇨 조절함','소변이 아예 안 나오는 경우는 드물기 때문에, <b>하루 한 번이라도 소변을 볼 때의 상태</b>로 기재하면 됩니다. 대부분의 투석 환자는 ''소변 조절함''으로 관리되고 있습니다.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,1,116),
('ask-pat-udiary-exempt','IN_PAT',NULL,'IN','CARD','치매 환자는 배뇨일지를 안 써도 되나요? (예외 요건)','치매 환자 배뇨일지 예외 요건','배뇨일지예외 치매상병 문제행동 행동증상약물 알츠하이머 혈관성치매 상세불명 MMSE','배뇨일지 작성 예외(중도 차목)는 <b>치매 상병 + 문제행동 기록 + 행동증상 약물</b>이 갖춰졌을 때 해당합니다.\n· 치매 상병은 알츠하이머(F00)만이 아니라 <b>상세불명·혈관성 치매도 가능</b>합니다. 알츠하이머 한정은 치매약을 행위별로 청구할 때의 기준일 뿐, 평가표에는 그런 제한이 없습니다.\n· 치매약 없이(행동증상 약물만) 적용하는 것도 기준상 가능하지만, 일부 지원(인천)은 치매약이 없으면 심사조정한 사례가 있어 소량이라도 병행 처방하는 것이 안전합니다. 의료중도(차목)로 청구했다가 인정받지 못하면 그 대상자가 다시 분모에 포함되므로 추가 관리가 필요합니다.\n· MMSE/GDS 점수가 낮아 요의 확인이 안 되는 대상자도 이 예외(치매+행동+약물)로 관리하는 방법을 검토합니다.',NULL,'ask-pat-udiary-3d','병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,3,117),
('ask-pat-udiary-when','IN_PAT',NULL,'IN','CARD','배뇨일지는 언제, 몇 시부터 작성하나요?','배뇨일지 작성 시점·시간','배뇨일지 작성시점 관찰기간 3일 오전 신규입원 다음날 시간간격 퇴원','평가표 관찰기간(작성일로부터 거꾸로 7일) 안에서 <b>연속 3일</b> 작성하면 됩니다(예: 관찰기간 1~3일째).\n· 배뇨훈련은 특별한 사유가 없으면 <b>오전부터</b> 시행합니다. 늦은 오후 입원한 신규 환자는 소변 조절 상태 파악이 안 된 상태이므로 <b>다음날부터</b>(또는 작성일로부터 거꾸로 3일) 시작하는 것이 맞습니다.\n· 시행 시간 간격(2시간·3시간 등)은 별도 규정이 없으며 <b>병원 의료진이 정한 계획</b>대로 하면 됩니다. 훈련 계획은 시행하는 날 오전에 작성해 두면 됩니다.\n· 의사 오더도 시행 3일에 맞춰 내면 됩니다.',NULL,'ask-pat-udiary-3d','병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,4,118),
('ask-pat-utrain-chart','IN_PAT',NULL,'IN','CARD','배뇨훈련 의무기록(오더·경과기록·간호기록)은 각각 어떻게 남기나요?','배뇨훈련 오더·경과·간호기록 남기는 법','배뇨훈련 지시오더 경과기록 SOAP 간호기록 예문 배뇨일지 서명 종결 듀티','<b>지시오더</b> — 예: ". Scheduled toileting plan 시행 / . 2시간 간격 화장실 유도 및 배뇨·실금 여부 관찰 및 배뇨일지 기록" 또는 "계획표에 따른 배뇨관리 시행(3일간)". 오더는 반드시 있어야 합니다.\n<b>경과기록(SOAP)</b> — 원칙은 환자 상태·계획을 담아 작성하고, 종결 시 원장이 최종 상태를 파악해 마무리하는 것입니다. 작성이 어려우면 최소한 지시오더라도 받아야 합니다.\n<b>간호기록</b> — 시행하는 날 1회 이상, 예: "배뇨훈련 오더에 따라 계획된 배뇨훈련 시행 중임. 1일 5회(06:00, 09:00, 12:00, 15:00, 18:00) 환자를 화장실로 이동시켜 배뇨를 유도함. 배뇨 여부·배뇨량·실금 양상을 관찰하여 배뇨일지에 기록함". 한 줄만 쓸 경우 시행 시간을 명시하고, 3일째 종결 시 "계획된 배뇨훈련 시행 및 배뇨일지 작성 완료하여 간호중재 종료함"을 남깁니다.\n<b>배뇨일지</b>만으로 관리하는 경우에는 일지에 간호사 서명이 들어가야 의무기록으로 인정됩니다. 배뇨일지와 훈련 중재 결과는 실제 배뇨했으면 ''배뇨''로 체크하면 됩니다.',NULL,'ask-pat-utrain-rec','병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,8,119),
('ask-pat-cic','IN_PAT',NULL,'IN','CARD','규칙적 도뇨(CIC)는 배뇨일지 없이 간호기록으로 대체되나요?','CIC는 간호기록으로 대체 가능?','규칙적도뇨 CIC 간헐도뇨 배뇨일지대체 도뇨오더','네. CIC(규칙적 도뇨)는 배뇨일지를 쓰지 않고 간호기록으로 대체해도 됩니다. 단, <b>도뇨 오더</b>는 반드시 받아 두어야 합니다.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,1,120),
('ask-pat-io-sheet','IN_PAT',NULL,'IN','CARD','배뇨일지와 I/O 기록지가 일치해야 하나요?','배뇨일지와 I/O 일치해야 하나요','배뇨일지 IO기록지 일치 경관식 유치도뇨관 필수여부','일치할 수 없습니다. 배뇨훈련을 시행하지 않는 밤 시간에도 기저귀 교환 등이 있으므로 <b>I/O가 더 많은 것이 정상</b>입니다.\nI/O 시트 자체도 필수는 아닙니다 — 간호기록·지시오더에서 (칼로리 계산에 따라 시간대별 섭취 내용을) 확인할 수 있으면 간호기록만으로 되고, 그렇지 않으면 별도 기록으로 관리합니다. 유치도뇨관 신뢰도 점검 제출 시에도 I/O 시트는 선택 자료입니다.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,2,121),
('ask-pat-sore-until','IN_PAT',NULL,'IN','CARD','욕창 처치·기록은 언제까지 계속해야 하나요?','욕창 처치·기록 언제까지','욕창처치 드레싱 체위변경 힐링 종료시점 평가표작성일 3일단위오더','힐링(개선) 예정인 욕창의 드레싱·체위변경 처치 오더와 체위변경표는 <b>해당월 평가표 작성일까지</b> 유지하면 됩니다. 힐링 후 평가표를 작성했다면(욕창 0) 그 작성일까지만 관련 기록을 유지하면 됩니다.\n욕창이 남아 있는 동안에는 처치가 연속되어야 하므로, 처치 오더를 3일 단위로 끊어 내기보다 완치 시까지 지속되도록 관리하는 것이 맞습니다.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,3,122),
('ask-pat-sore-nutrition','IN_PAT',NULL,'IN','CARD','욕창 영양공급은 칼로리·단백질 중 하나만 맞추면 되나요?','욕창 영양 칼로리·단백질 요건','욕창 영양공급 칼로리 단백질 30kcal 처방오더 간호기록 계산','네, <b>칼로리 ''또는'' 단백질</b> 요건이므로 한 가지를 충족하면 됩니다. 단, 한 가지 안에서 채워야 하고 칼로리 부족분을 단백질로 대신 채울 수는 없습니다.\n간호기록에 계산 내용(예: 체중 40kg → 필요 40×30=1,200kcal / 섭취 1,200kcal / 부족 0kcal)을 남긴다면, 같은 내용이 <b>의사 처방오더에도</b> 있어야 합니다. 의사가 중간에 칼로리를 증액했다면 오더도 함께 수정되어야 합니다.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,4,123),
('ask-pat-homevent','IN_PAT',NULL,'IN','CARD','가정용 인공호흡기(홈벤트)를 평가표에서 빼도 되나요?','홈벤트 평가표에서 빼도 되나요','가정용인공호흡기 홈벤트 평가표 처방전 공단지원','안 됩니다. 환자가 개인 임대로 쓰고 있어 병원이 청구하지 않더라도, 인공호흡기 처방전을 발급받은(공단 지원) 환자라면 평가표에서 가정용 인공호흡기를 빼면 추후 문제가 될 수 있습니다.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,1,124),
('ask-pat-cognition','IN_PAT',NULL,'IN','CARD','''가끔 실금''으로 관리하려면 인지기능 항목은 어떻게 체크돼야 하나요?','가끔실금과 인지기능 정합성','인지기능 의사결정 인식기술 이해시키는능력 가끔실금 정합성 다소손상','''가끔 실금함''(요의 인지 전제)과 어긋나지 않으려면 인지 항목이 지나치게 낮으면 안 됩니다.\n· 일상 의사결정 인식기술: ''스스로 일관성 있음'' ~ ''새로운 상황에서만 (곤란)'' 수준. ''다소 손상됨''도 가능하지만 차팅에서 대화 가능 등 근거가 확인되어야 합니다.\n· 이해시키는 능력: ''이해시킴'' ~ ''대부분 이해시킴''(가끔 이해시킴도 의무기록으로 확인되면 가능).\n한꺼번에 바꾸기보다 <b>의무기록 작성부터 맞춘 뒤</b> 평가표를 맞추는 순서가 안전합니다.',NULL,'ask-pat-urine-record','병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,1,125);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,HIT_CNT,SORT_NO) VALUES
('ask-ind-psy-scope','IN_IND',NULL,'IN','CARD','항정신성의약품 처방률에는 어떤 처방이 포함되나요?','항정 처방률 포함 범위','항정신성의약품 처방률 주사제 타병원외래 추가청구 격리 CRE 재입원 자보 산재 건보 의료급여 보훈 월1회 큐로켈','포함 범위가 넓습니다.\n· <b>주사제도 포함</b>됩니다(경구만이 아님).\n· 입원 중 타병원 외래진료 처방을 <b>추가청구하면 포함</b>됩니다.\n· <b>CRE 등 격리 환자도 포함</b>됩니다.\n· 월 중 <b>1일이라도 처방되면 그 달의 처방 대상자</b>로 집계됩니다.\n· 적용 보험은 <b>건강보험·의료급여·보훈만</b>이며, 자보·산재는 포함되지 않습니다.\n· 퇴원 후 재입원하면 <b>다른 환자로 간주</b>되어 새로 계산됩니다.\n참고로 심평원의 65세 이상 항정신병제 처방현황 조사는 1명이 2종 투약 시 2건으로 세며, 같은 성분을 낮은 용량 여러 정으로 쪼개면 건수가 늘어나므로(0.5mg 2T=2건, 1mg 1T=1건) 처방현황 관리에는 불리합니다.',NULL,'ask-pat-quetiapine','병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,6,101),
('ask-ind-sore-newonset','IN_IND',NULL,'IN','CARD','격리(전월 평가표 없음) 해제 후 욕창이 있으면 신규발생인가요?','격리해제 후 욕창 = 신규발생?','격리해제 욕창신규발생 전월평가표없음 이전평가표 3개월 비교값','아닙니다. 신규발생 욕창은 <b>전월 평가표와 비교</b>해서 판정하므로, 격리 등으로 <b>전월 평가표가 없었던 환자는 비교값이 없어 신규발생으로 잡히지 않습니다</b>. 프로그램이 신규발생으로 체크하더라도 발생일은 기재하지 않는 것이 맞습니다.\n단, 격리가 3개월을 넘겨 이전평가표 적용(최근 3개월 이내)도 불가능한 경우라도 해제 후 첫 평가표에 욕창을 기재하고 작성하면 되고, 이때도 신규발생·개선 분모에는 포함되지 않습니다. 이후 달부터는 평가표가 연속되므로, 다음 평가에서 욕창이 그대로 있으면 개선 분모에, 없던 욕창이 생기면 신규발생에 잡히기 시작합니다.',NULL,'ask-ind-sore-denom','병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,4,102),
('ask-ind-longstay','IN_IND',NULL,'IN','CARD','장기입원환자분율에 다른 병원 입원기간도 합산되나요?','장기입원분율에 타병원 기간 합산?','장기입원환자분율 181일 체감제 타병원합산 재입원90일 경도 선택입원군 격리','네, 그럴 수 있습니다. 장기입원(181일) 판정은 <b>요양병원 입원료 체감제 수가</b>(181일·361일 이상 입원료 코드)로 산출되는데, 체감제는 퇴원 후 90일 이내 재입원 시 <b>이전 요양병원 입원기간을 합산</b>하므로 우리 병원 입원이 짧아도 분자에 집계될 수 있습니다.\n분모·분자 대상은 의료경도·선택입원군 환자이며, 격리 환자도 181일을 초과하면 포함됩니다.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,2,103),
('ask-ind-grade-cut','IN_IND',NULL,'IN','CARD','1등급·상위 10% 컷 점수는 어느 정도였나요?','1등급·상위10% 컷 점수','1등급컷 종합점수 상위10% 상위30% 표준화구간 결과발표 87점 85점','과거 결과발표 기준으로 참고하세요(매 회차 표준화 구간이 바뀌므로 확정치가 아닙니다).\n· 1등급 컷: 2023년 결과발표 약 87점 → 2024년 약 85점.\n· 상위 10%: 두 해 모두 약 89.2점부터 / 상위 10~30%: 2023년 84.3점, 2024년 81.3점부터 시작(진행 기관 실측 기준).\n2025년 결과발표부터는 상향 조정이 예상되어, 상위 10% 이내를 목표한다면 <b>90점</b>을 기준으로 관리하는 것이 안전합니다.',NULL,'ask-ind-result-when','병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,4,104),
('ask-ind-wincheck','IN_IND',NULL,'IN','CARD','윈체크 점검 표시(빨간불·가중치 0점)는 무슨 뜻인가요?','윈체크 빨간불·가중치0 의미','윈체크 wincheck ADL빨간불 가중치0점 지표제외 재산출 점검사유 A1','· <b>ADL 빨간 표시</b>: 전월 대비 변동이 있을 때 확인용으로 표시되는 것으로, 오류라는 뜻이 아닙니다.\n· <b>지표 가중치 0점</b>(예: 장기입원환자분율): 해당 지표의 대상자가 없다는 뜻입니다. 지표명 옆 파란색 체크를 해제하면 <b>해당 지표 제외 후 재산출 값</b>으로 종합점수를 확인할 수 있습니다(지표 구성이 달라지므로 단순 합산과는 점수가 다르게 나옵니다).\n· 적정성평가 점검 화면에서 A1 등 점검 코드에 마우스를 올리면 점검 사유가 표시됩니다.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,2,105),
('ask-ind-dur-cancel','IN_IND',NULL,'IN','CARD','DUR 점검에서 ''취소''된 건은 재점검해야 하나요?','DUR 취소건 재점검해야 하나요','DUR 취소 재점검 처방전교부번호 완료 퇴원환자 DC 누락리스트 완료현황','처방전 교부번호 기준으로 판단합니다.\n· 완료된 뒤 <b>다시 취소</b>되었다면 → 재점검(재전송)해야 합니다.\n· 완료 이후 취소가 없으면 → 1건이라도 완료됐으므로 넘어가도 됩니다.\n· <b>퇴원 환자에게 잘못 낸 오더를 취소</b>한 건, 당일 D/C된 약의 취소 건은 취소로 끝나는 것이 맞고 재점검 대상이 아닙니다.\n프로그램의 ''DUR 점검 누락리스트''는 편의 기능이므로 참고만 하고, <b>매월 심평원 DUR 완료현황을 기준</b>으로 확인하세요. 오더는 있는데 심평원 명단에서 아예 확인되지 않는 대상자가 있는지, 각 진료실 PC에서 처방 시 DUR 전송이 정상 동작하는지(일부 PC 미실행 사례 있음)도 평가기간 전 점검이 필요합니다.',NULL,'ask-fee-dur','병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,3,106),
('ask-ind-reliability-docs','IN_IND',NULL,'IN','CARD','신뢰도(오류) 점검 때 어떤 의무기록을 제출하나요?','신뢰도 점검 제출자료','신뢰도점검 오류점검 제출서류 IO시트 폐렴 패혈증 경과기록 의사기록지 변경요청서 e평가시스템','· 유치도뇨관 대상자의 I/O 시트는 <b>선택</b> 자료입니다(필수 아님).\n· 폐렴·패혈증 특정기간이 있으면 해당 기간 의무기록도 <b>함께 제출</b>해야 합니다.\n· "의사기록지 또는 경과기록지"처럼 ''또는''으로 안내된 항목은 <b>하나만</b> 내면 되고, 의사지시기록을 제출해도 됩니다.\n· 욕창의 공기침대 등 압력분산 도구는 지시오더가 없어도 간호기록에서 관리 내용이 확인되면 통상 인정되지만, 평가기간 내 1일이라도 오더가 있으면 더 안전합니다.\n· 오류점검 대상자의 평가표 수정은 제출 후 심평원이 <b>환자평가표 변경 요청서</b> 제출을 별도로 안내하며, 수정 내역 확인 기간에 e-평가시스템 평가알림방 게시글을 확인하면 됩니다.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,5,107),
('ask-ind-sorecare-npo','IN_IND',NULL,'IN','CARD','금식·영양제한 욕창 환자는 욕창처치 분율에서 빠지나요?','금식 욕창환자 처치분율 예외?','욕창처치분율 금식 영양공급제한 95% 신뢰도점검 환류 현지조사','욕창처치 환자분율은 95% 이상 수준으로 집계되는 지표라 여유가 거의 없습니다.\n금식·영양공급 제한 환자의 처치 인정 여부는 <b>심평원 담당자에 따라 답변이 갈립니다</b> — 신뢰도 점검에서는 환자 상태를 반영해 준다고 안내하지만, 환류기관 컨설팅 과정에서 인정되지 않은 사례도 있었습니다. 해당 항목을 체크하더라도 현지조사에서 인정되지 않을 가능성을 감안하고 적용해야 합니다.',NULL,'ask-ind-sorecare-denom','병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,1,108);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,HIT_CNT,SORT_NO) VALUES
('ask-fee-bladder-scan','IN_FEE',NULL,'IN','CARD','방광 잔뇨량 검사(방광스캐너)가 삭감되는 이유는?','방광스캐너 삭감 이유','방광스캐너 잔뇨량검사 심사조정 삭감 재심 의무기록','2026년 3~4월부터 방광스캐너(잔뇨량 검사) 심사조정이 시작되어 지원별로 확산되고 있습니다.\n조정 유형은 ① 보유 장비 대수 대비 청구량이 과다한 경우 ② 동일 환자에게 일정하게 반복 청구되는 경우 ③ 진단·질병 근거가 없고 청구 메모에서도 사유가 확인되지 않는 경우입니다. 자료 요청 없이 일괄 1/3~1/2 비율로 조정된 사례가 많습니다.\n조정된 경우 <b>의무기록을 첨부해 재심(이의신청)</b>을 진행하는 기관들이 있습니다.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,1,101),
('ask-fee-egf','IN_FEE',NULL,'IN','CARD','이지에프외용액은 정액수가와 별도로 청구할 수 있나요?','이지에프외용액 별도청구 가능?','이지에프외용액 EGF 정액수가 별도산정 특정항목 전문의약품','네. 이지에프외용액(Recombinant Human EGF)은 <b>정액수가에 포함되지 않고 별도 산정할 수 있는 전문의약품</b>입니다(수가 산정지침 특정항목). 정액수가 포함으로 잘못 알려진 경우가 있으니 주의하세요.',NULL,'pdf-0210','병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,1,102),
('ask-fee-infection-doc','IN_FEE',NULL,'IN','CARD','감염관리실 의사는 겸직해도 되나요? (감염예방관리료 인력)','감염관리실 의사 겸직 가능?','감염관리실 의사겸직 QPS 감염예방관리료 300병상 전담간호사 교육이수','의사는 다른 위원회(QPS 등)와 <b>겸직해도 무방</b>합니다. 감염관리 의사는 300병상당 1명 기준이라 1명만 있어도 되고, 교육 이수(매년 16시간 이상)와 경력 요건을 갖추면 수가 산정이 가능합니다.\n<b>전담이어야 하는 것은 간호사</b>입니다(병상 규모 무관).',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,1,103),
('ask-fee-jabo-to-nhis','IN_FEE',NULL,'IN','CARD','자보 종결 후 건강보험으로 전환 청구해도 되나요?','자보 종결 후 건보 전환 청구','자동차보험 종결 건강보험전환 급여제한여부조회 입원신고 교통사고','가능합니다. 자보 종결 후 건보로 변경하는 것은 공단 입원신고만 하면 크게 문제되지 않으나, 교통사고로 인한 상병(사지마비 등)이 이어지는 경우라면 <b>건강보험 급여제한 여부 조회</b>(별지 제2호서식)를 신청한 뒤 진행하는 것이 안전합니다. 급여제한이 아니라고 회신되면 그대로 건보 청구가 가능합니다.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,1,104),
('ask-fee-retired-order','IN_FEE',NULL,'IN','CARD','퇴사한 의사가 미리 내놓은 정규처방을 그대로 써도 되나요?','퇴사 의사 선오더 사용 가능?','퇴사의사 선오더 정규처방 신규의사 현지조사 법적책임','원칙은 <b>새로 온 의사 명의로 오더를 다시 내는 것</b>입니다. 다만 약국 조제 시간 확보 등을 위해 기존 원장 명의 선오더를 쓰는 기관이 많고, 현지조사에서 퇴사 원장 오더 자체가 문제된 사례는 없습니다. 단, 해당 약물로 법적 문제가 발생하면 처방의 책임 문제가 생길 수 있다는 점은 감안해야 합니다.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,1,105),
('ask-fee-dressing-sites','IN_FEE',NULL,'IN','CARD','염증성처치는 몇 부위까지 산정되나요?','염증성처치 부위 수','염증성처치 7부위 두부 복부 배부 상지 하지 드레싱 전신','부위 구분은 <b>두부·복부·배부·좌상지·우상지·좌하지·우하지의 7부위</b>입니다. 전신 드레싱이라도 병변이 없는 부위는 뺀 부위 수만 인정됩니다(예: 두부에 병변이 없으면 최대 6부위).',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,1,106),
('ask-fee-discharge-summary','IN_FEE',NULL,'IN','CARD','퇴원요약지는 누가 작성하나요? (사망·응급퇴원 시)','퇴원요약지 작성자','퇴원요약지 주치의 사망퇴원 응급퇴원 당직의','퇴원요약지는 <b>주치의</b>가 작성합니다. 사망 당일 주치의가 부재였다면 출근 후 작성하면 됩니다(퇴원 지시를 낸 당직의가 아니어도 됩니다).',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,1,107),
('ask-fee-duty-log','IN_FEE',NULL,'IN','CARD','의사 당직일지는 언제 작성하나요? (평일·주말·공휴일)','의사 당직일지 작성 범위','당직일지 평일 야간 주말 공휴일 근무표 인증','정규 근무가 아닌 <b>당직으로 근무하는 시간대는 모두</b> 당직일지를 작성한다고 생각하면 됩니다.\n· 평일 낮: 의사 근무표로 갈음, 매일 저녁(야간) 당직일지는 작성해 관리.\n· 주말·공휴일: 오전에 다른 원장이 당직 업무를 했다면 그 시간대도 작성.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,1,108),
('ask-fee-protein-diet','IN_FEE',NULL,'IN','CARD','일반식에 단백질파우더를 추가하면 고단백식(치료식)이 되나요?','일반식+단백질파우더=치료식?','고단백식 치료식 단백질파우더 일반식 식대코드','아닙니다. 일반식에 단백질파우더를 추가해도 <b>일반식</b>이며, 치료식(고단백식) 코드로 입력할 수 없습니다.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,1,109),
('ask-fee-parttime-nurse','IN_FEE',NULL,'IN','CARD','단시간(일용직) 간호사도 인력 차등제에 반영되나요?','단시간 간호사 인력가산 반영?','단시간간호사 일용직 4대보험 공단신고 차등제 인력가산','간호인력 차등제에 반영하려면 <b>공단(건강보험공단) 인력 신고가 필요</b>합니다. 4대보험 가입 없는 일용직 형태로는 인력가산에 반영할 수 없습니다.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,1,110),
('ask-fee-jardiance','IN_FEE',NULL,'IN','CARD','당뇨가 없는 환자에게 자디앙(SGLT2)을 심혈관 목적으로 쓰면?','당뇨 없는 자디앙 처방','자디앙 SGLT2 당뇨병용제 심부전 심혈관 상병 R81 당화혈색소','자디앙은 심혈관질환에도 쓰이지만 식약처·심평원 분류상 <b>당뇨병용제</b>입니다.\n당뇨가 없는 환자에게 투여해야 한다면 당뇨 상병(E11~E14) 대신 실제 상태에 맞는 상병·증상코드(예: R81)를 기재해 청구하거나, 당화혈색소 검사를 시행해 관리 근거를 남기는 것이 안전합니다. E코드를 넣으면 당화혈색소 지표 분모에 들어가는 점도 함께 고려해야 합니다.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,1,111),
('ask-fee-jabo-acupuncture','IN_FEE',NULL,'IN','CARD','자보 외래 침술·부항·약침의 인정 횟수는?','자보 침·부항·약침 인정 횟수','자동차보험 외래 침술횟수 습식부항 약침 수상일 주3회 주2회','자보 심사자문위원회 심의 결과 기준입니다(요양병원 <b>입원</b> 침술의 주당 횟수 제한은 2019년부터 없어짐).\n· <b>침술(외래)</b>: 염좌·긴장 등 경미한 상해는 수상일로부터 3주까지 매일, 11주까지 주3회, 26주까지 주2회, 27주부터 주1회(초과 시 해당일 치료비 전액 조정). 골절 등은 +2일 정도 여유.\n· <b>습식부항</b>: 최초 시술일부터 1주 이내 매일, 1~3주 주4회, 3주 이후 주2회.\n· <b>약침</b>: 외래·입원 1일 1회 — 수상일로부터 1주까지 매일, 2~3주 주3회, 4~10주 주2회, 10주 초과 주1회(골절은 사례별 추가 인정).',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,1,112),
('ask-fee-chuna','IN_FEE',NULL,'IN','CARD','요양병원에서 자보 추나요법을 산정할 수 있나요?','요양병원 자보 추나 가능?','추나요법 자보 한방의료기관 요양병원불가 심사결정 보험사청구','안 됩니다. 추나요법은 <b>한방의료기관으로 인정받은 기관만</b> 산정할 수 있어, 요양병원에서는 한의사가 교육을 이수했더라도 자보 추나 산정이 불가합니다.\n참고로 자보는 삭감되더라도 보험회사에는 <b>심평원 심사 결정 후 금액만</b> 청구됩니다.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,2,113),
('ask-fee-dialysis-sanjeong','IN_FEE',NULL,'IN','CARD','투석 환자 산정특례는 언제부터 신청할 수 있나요?','투석 산정특례 신청 시점','투석 산정특례 신부전 만성콩팥병 신청시점 3개월 중복등록 치매 파킨슨','투석 3개월 경과 같은 대기 요건은 없습니다. 신부전증으로 투석을 시작했다면 <b>신청 후 바로 적용</b>됩니다(만성 콩팥병도 등록 범위 상병에 해당).\n투석을 주기적으로 받고 있는데 산정특례 등록이 안 되어 있다면, 실제로 투석을 시행한 기관에 등록을 요청해야 합니다.\n중증치매 산정특례가 있는 환자도 다른 항목(파킨슨 등)의 산정특례는 별도로 등록된 사례가 있습니다.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,2,114),
('ask-fee-consult','IN_FEE',NULL,'IN','CARD','요양병원에서 협의진찰료는 언제 산정할 수 있나요?','협의진찰료 산정 요건','협의진찰료 협진 한방 양방 의과 재활의학과 신경과','요양병원의 협의진찰료는 <b>한방↔양방(의과) 간 협진</b>일 때만 산정할 수 있습니다. 행위별 환자라도 의과↔의과(예: 신경과→재활의학과) 협진은 산정해 청구해도 인정되지 않습니다(원내 확인용 산정은 무방).',NULL,'pdf-0280','병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,1,115),
('ask-fee-neuro-rehab','IN_FEE',NULL,'IN','CARD','말초신경질환(길랭바레 등)의 전문재활은 어디까지 인정되나요?','말초신경질환 전문재활 인정범위','길랭바레 말초신경질환 NDT 매트치료 MM301 온셋 1일2회','말초신경질환은 중추신경계발달재활치료(NDT)가 인정되지 않고, <b>매트 및 이동치료(MM301)·보행치료까지만</b> 가능합니다.\n실시 횟수는 발병일(onset) 기준으로 판단하며, 온셋 1년 이내라면 매트치료 1일 2회 인정이 원칙입니다. 그런데도 조정된 경우에는 심사조정한 지원에 직접 소통(재심)이 필요합니다.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05, 8개 병원) — 위너넷 컨설팅 답변',0,20,1,116);
